    send: async (input) => {
      sent.push(input)
      return { deliveryId: "cio-1", queuedAt: 1_786_272_000 }
    },
    settle: async (_claim, outcome) => {
      settled.push(outcome)
    },
  })

  assert.deepEqual(result, {
    claimed: 1,
    queued: 1,
    retryable: 0,
    supportRequired: 0,
    blocked: false,
